package ecommerce_user_service.support;

import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.context.request.RequestAttributes;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

/**
 * Runtime helpers implementing the Datrix {@code Request} builtin category's static, receiver-less
 * current-request accessors ({@code ip}/ {@code userAgent}/{@code device}/{@code header}/{@code
 * cookie}/ {@code bearerToken}).
 *
 * <p>Auto-generated by datrix-codegen-java. Do not edit manually.
 */
public final class RequestHelpers {

  private RequestHelpers() {}

  /** {@code Request.ip()} -- the current request's remote client address. */
  public static String ip() {
    return currentRequest().getRemoteAddr();
  }

  /** {@code Request.userAgent()} -- the current request's {@code User-Agent} header. */
  public static String userAgent() {
    return orEmpty(currentRequest().getHeader("User-Agent"));
  }

  /**
   * {@code Request.device()} -- device info derived from the user agent. Matches python's own
   * reference mapping exactly: no dedicated UA parsing, the same raw {@code User-Agent} header
   * value as {@link #userAgent()}.
   */
  public static String device() {
    return userAgent();
  }

  /** {@code Request.header(name)} -- one named header from the current request. */
  public static String header(String name) {
    return orEmpty(currentRequest().getHeader(name));
  }

  /**
   * {@code Request.cookie(name)} -- one named cookie's value from the current request, or {@code
   * null} if absent (matches python's {@code request.cookies.get(name)} -- a bare {@code dict.get},
   * not defaulted).
   */
  public static String cookie(String name) {
    Cookie[] cookies = currentRequest().getCookies();
    if (cookies == null) {
      return null;
    }
    for (Cookie c : cookies) {
      if (c.getName().equals(name)) {
        return c.getValue();
      }
    }
    return null;
  }

  /**
   * {@code Request.bearerToken()} -- the current request's {@code Authorization} header with a
   * leading {@code "Bearer "} prefix stripped, matching python's {@code .removeprefix('Bearer ')}
   * semantics exactly (no prefix present -> the header value returned unchanged).
   */
  public static String bearerToken() {
    String authHeader = orEmpty(currentRequest().getHeader("Authorization"));
    return authHeader.startsWith("Bearer ") ? authHeader.substring(7) : authHeader;
  }

  private static String orEmpty(String value) {
    return value != null ? value : "";
  }

  /**
   * Resolve the {@link HttpServletRequest} bound to the current thread by Spring MVC's {@code
   * DispatcherServlet} for the duration of the in-flight request.
   *
   * @throws IllegalStateException if called outside a Spring MVC request-handling thread (an async
   *     worker, a scheduled job, or after the response has already completed) -- these accessors
   *     only resolve on the SAME thread that is currently dispatching the HTTP request (or
   *     something it calls synchronously, matching every real {@code Request.*} call site:
   *     `03-domains-ecommerce`'s own calls are evaluated as ordinary handler-body
   *     expressions/`dispatch` arguments, both on that thread).
   */
  private static HttpServletRequest currentRequest() {
    RequestAttributes attributes = RequestContextHolder.currentRequestAttributes();
    if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
      throw new IllegalStateException(
          "Request.ip()/userAgent()/device()/header()/cookie()/bearerToken() require an "
              + "active Spring MVC (Servlet) request context, but the current thread's bound "
              + "RequestAttributes was a "
              + attributes.getClass().getSimpleName()
              + ", not a ServletRequestAttributes.");
    }
    return servletAttributes.getRequest();
  }
}
